"""Editable solution file for open-ended stateful query-engine search.

Agents may replace this file during an open-ended run. The evaluator imports
`CandidateQueryEngine` and checks it against the hidden reference engine before
performance is measured.
"""

from __future__ import annotations


class CandidateQueryEngine:
    """Correct list-backed baseline implementation."""

    def __init__(self, items: dict[int, int] | None = None):
        self._items: list[tuple[int, int]] = []
        if items:
            for key, value in items.items():
                self.put(key, value)

    def put(self, key: int, value: int) -> None:
        key = int(key)
        value = int(value)
        for index, (existing_key, _) in enumerate(self._items):
            if existing_key == key:
                self._items[index] = (key, value)
                return None
        self._items.append((key, value))
        return None

    def delete(self, key: int) -> None:
        key = int(key)
        self._items = [
            (existing_key, value)
            for existing_key, value in self._items
            if existing_key != key
        ]
        return None

    def get(self, key: int) -> int | None:
        key = int(key)
        for existing_key, value in self._items:
            if existing_key == key:
                return value
        return None

    def range_sum(self, lo: int, hi: int) -> int:
        lo = int(lo)
        hi = int(hi)
        if lo > hi:
            return 0
        total = 0
        for key, value in self._items:
            if lo <= key <= hi:
                total += value
        return total

    def aggregate_count(self, lo: int, hi: int) -> int:
        lo = int(lo)
        hi = int(hi)
        if lo > hi:
            return 0
        count = 0
        for key, _ in self._items:
            if lo <= key <= hi:
                count += 1
        return count

    def top_k(self, lo: int, hi: int, k: int) -> list[tuple[int, int]]:
        lo = int(lo)
        hi = int(hi)
        k = int(k)
        if lo > hi or k <= 0:
            return []
        rows = [(key, value) for key, value in self._items if lo <= key <= hi]
        rows.sort(key=lambda item: (-item[1], item[0]))
        return rows[:k]

"""Indexing-mode candidate: dictionary plus sorted-key range access."""

from __future__ import annotations

import bisect


class CandidateQueryEngine:
    def __init__(self, items: dict[int, int] | None = None):
        self._values: dict[int, int] = {int(key): int(value) for key, value in (items or {}).items()}
        self._keys: list[int] = sorted(self._values)

    def put(self, key: int, value: int) -> None:
        key = int(key)
        if key not in self._values:
            bisect.insort(self._keys, key)
        self._values[key] = int(value)
        return None

    def delete(self, key: int) -> None:
        key = int(key)
        if key not in self._values:
            return None
        del self._values[key]
        index = bisect.bisect_left(self._keys, key)
        if index < len(self._keys) and self._keys[index] == key:
            self._keys.pop(index)
        return None

    def get(self, key: int) -> int | None:
        return self._values.get(int(key))

    def range_sum(self, lo: int, hi: int) -> int:
        left, right = self._range_bounds(lo, hi)
        return sum(self._values[key] for key in self._keys[left:right])

    def aggregate_count(self, lo: int, hi: int) -> int:
        left, right = self._range_bounds(lo, hi)
        return max(0, right - left)

    def top_k(self, lo: int, hi: int, k: int) -> list[tuple[int, int]]:
        left, right = self._range_bounds(lo, hi)
        k = int(k)
        if left >= right or k <= 0:
            return []
        rows = [(key, self._values[key]) for key in self._keys[left:right]]
        rows.sort(key=lambda item: (-item[1], item[0]))
        return rows[:k]

    def _range_bounds(self, lo: int, hi: int) -> tuple[int, int]:
        lo = int(lo)
        hi = int(hi)
        if lo > hi:
            return 0, 0
        return bisect.bisect_left(self._keys, lo), bisect.bisect_right(self._keys, hi)
